export function computeInvoice({ lines, discountKobo = 0 }) {
  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }
  if (!Number.isInteger(discountKobo) || discountKobo < 0) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  let invoiceSubtotal = 0;
  const lineDetails = lines.map(line => {
    const { sku, unitPriceKobo, qty, vatExempt } = line;
    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError("unitPriceKobo must be a non-negative integer");
    }
    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError("qty must be a positive integer");
    }

    const lineSubtotal = unitPriceKobo * qty;
    invoiceSubtotal += lineSubtotal;

    return {
      sku,
      lineSubtotal,
      vatExempt
    };
  });

  const appliedDiscount = Math.min(discountKobo, invoiceSubtotal);

  let totalAllocatedDiscount = 0;
  const allocations = lineDetails.map(line => {
    const fractionalAllocation = appliedDiscount * line.lineSubtotal / invoiceSubtotal;
    const floorAllocation = Math.floor(fractionalAllocation);
    totalAllocatedDiscount += floorAllocation;
    return {
      sku: line.sku,
      floorAllocation,
      remainder: fractionalAllocation - floorAllocation,
      lineSubtotal: line.lineSubtotal,
      vatExempt: line.vatExempt
    };
  });

  const leftoverDiscount = appliedDiscount - totalAllocatedDiscount;
  allocations.sort((a, b) => b.remainder - a.remainder || lines.indexOf(a) - lines.indexOf(b));

  for (let i = 0; i < leftoverDiscount; i++) {
    allocations[i].floorAllocation += 1;
  }

  let totalVatKobo = 0;
  const computedLines = allocations.map(({ sku, floorAllocation, lineSubtotal, vatExempt }) => {
    const netKobo = lineSubtotal - floorAllocation;
    const lineVatKobo = vatExempt ? 0 : Math.round(netKobo * 0.075);
    totalVatKobo += lineVatKobo;

    return {
      sku,
      subtotalKobo: lineSubtotal,
      discountKobo: floorAllocation,
      netKobo,
      vatKobo: lineVatKobo
    };
  });

  const totalKobo = invoiceSubtotal - appliedDiscount + totalVatKobo;

  return {
    subtotalKobo: invoiceSubtotal,
    discountKobo: appliedDiscount,
    vatKobo: totalVatKobo,
    totalKobo,
    lines: computedLines
  };
}
